 * @param {String} miscPrtdepoEndDd miscPrtdepoEndDd
 * @param {String} miscPrtdepoRsnCd miscPrtdepoRsnCd
 * @param {String} prtWithdYn prtWithdYn
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (bzProcsNo, prtdepoId, prtdepoPrnTpCd, prtdepoStrtDd, prtdepoEndDd, nm, resdbzRegNo, prtdepoObjKindCd, prtdepoObjTpCd, prtdepoRsnCd, prtdepoRsnMngrghtTpCd, prtdepoRsnFncTpCd, prtdepoObjTpMiscContn, prtdepoShrs, miscPrtdepoStrtDd, miscPrtdepoEndDd, miscPrtdepoRsnCd, prtWithdYn) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent("dma_RegisterReq").set("prtdepoId", prtdepoId);
    (($c.util.getComponent('slc_prtdepoPrnTpCd'))?.setValue?.(prtdepoPrnTpCd));
    $c.util.getComponent('cal_prtdepoStrtDd').setValue(prtdepoStrtDd);
    $c.util.getComponent('cal_prtdepoEndDd').setValue(prtdepoEndDd);
    $c.util.getComponent('ipt_nm').setValue(nm);
    $c.util.getComponent('ipt_resdbzRegNo').setValue(resdbzRegNo);
    (($c.util.getComponent('slc_prtdepoObjKindCd'))?.setValue?.(prtdepoObjKindCd));
    scwin.onChangeObjKindCd();
    (($c.util.getComponent('slc_prtdepoObjTpCd'))?.setValue?.(prtdepoObjTpCd));
    scwin.onChangeObjTpCd();
    (($c.util.getComponent('slc_prtdepoRsnCd'))?.setValue?.(prtdepoRsnCd));
    scwin.onChangeObjRsnCd();
    (($c.util.getComponent('slc_prtdepoRsnMngrghtTpCd'))?.setValue?.(prtdepoRsnMngrghtTpCd));
    scwin.onChangeObjRsnMnCd();
    (($c.util.getComponent('slc_prtdepoRsnFncTpCd'))?.setValue?.(prtdepoRsnFncTpCd));
    $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue(prtdepoObjTpMiscContn);
    $c.util.getComponent('ipt_prtdepoShrs').setValue($c.num.formatNumber(prtdepoShrs));
    (($c.util.getComponent('slc_miscPrtdepoRsnCd'))?.setValue?.(miscPrtdepoRsnCd));
    $c.util.getComponent("dma_RegisterReq").set("prtWithdYn", prtWithdYn);
    $c.util.getComponent('cal_miscPrtdepoStrtDd').setValue(miscPrtdepoStrtDd);
    $c.util.getComponent('cal_miscPrtdepoEndDd').setValue(miscPrtdepoEndDd);
    scwin.onloadDataSet();
};

