/**
 * @method
 * @name specialWord
 * @description special Word 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.specialWord = async function () {
    let nm = ($c.util.getComponent("ipt_nm").getValue() || '');
    if (nm.indexOf("\\") !== -1) {
        nm = nm.replace(/\\/g, "");
        $c.util.getComponent("ipt_nm").setValue(nm);
        await $c.win.alert("\\는 입력할 수 없습니다");
    }
    if (nm.indexOf("\"") !== -1) {
        nm = nm.replace(/"/g, "");
    $c.util.getComponent("ipt_nm").setValue(nm);
    await $c.win.alert("\"는 입력할 수 없습니다");
    }
};

/**
 * @method
 * @name exceptWord
 * @description except Word 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.exceptWord = async function () {
    let resdbzRegNo = $c.util.getComponent('ipt_resdbzRegNo').getValue();
    if (resdbzRegNo.indexOf("\'") !== -1) {
        resdbzRegNo = resdbzRegNo.replace(/'/g, "");
    $c.util.getComponent('ipt_resdbzRegNo').setValue(resdbzRegNo);
    await $c.win.alert("'는 입력할 수 없습니다");
}
};
